    reactionName(name) {
        const isUnicodeEmoji = /\p{Emoji_Modifier_Base}\p{Emoji_Modifier}?|\p{Emoji_Presentation}|\p{Emoji}\uFE0F/gu.test(name);
        if (isUnicodeEmoji) {
            return name;
        }
        return `:${name}:`;
    }
